#include<bits/stdc++.h>
using namespace std;

const long long MOD1 = 998244353LL;
const long long MOD2 = 1000000007LL;
long long N;
int d[15], b[15], ans;

long long get_num(int *arr, int len) {
    long long r = 0;
    for (int i = 1; i <= len; ++i) r = r * 10 + arr[i];
    return r;
}

long long get_rank(int *arr, int len) {
    long long r = 0;
    for (int L = 1; L <= d[0]; ++L) {
        int lim = min(len, L);
        for (int i = 1; i <= lim; ++i) {
            int lo = (i == 1) ? 1 : 0;
            for (int j = lo; j < arr[i]; ++j) {
                long long l = 0, ri = 0;
                for (int p = 1; p < i; ++p) l = ri = l * 10 + arr[p];
                l = ri = l * 10 + j;
                for (int p = i + 1; p <= L; ++p) {
                    l = l * 10;
                    ri = ri * 10 + 9;
                }
                if (ri > N) ri = N;
                if (l <= ri) r += ri - l + 1;
            }
        }
        if (L <= len) ++r;
    }
    return r;
}

int F(int *arr, int len) {
    long long num = get_num(arr, len);
    long long rnk = get_rank(arr, len);
    return (int)(( - num + rnk) % MOD1 + MOD1) % (int)MOD1;
}

int diff[15];
int q1[1000010];
int q2[1000010];
long long sq2[1000010];

void gen(int t, int ed, int *q, int v) {
    if (t == ed) {
        for (int i = 0; i <= 9; ++i)
            q[++q[0]] = (v + 1LL * i * diff[t]) % MOD1;
        return;
    }
    for (int i = 0; i <= 9; ++i)
        gen(t + 1, ed, q, (v + 1LL * i * diff[t]) % MOD1);
}

void upd(int di, int i, int j) {
    memcpy(b, d, sizeof(b));
    b[i] = j;
    for (int p = i + 1; p <= di; ++p) b[p] = 0;
    int bas = F(b, di);
    for (int p = i + 1; p <= di; ++p) {
        b[p] = 1;
        diff[p] = (F(b, di) - bas + MOD1) % MOD1;
        b[p] = 0;
    }
    if (di - i == 0) {
        ans = (ans + bas) % MOD2;
        return;
    }
    if (di - i == 1) {
        for (int p = 0; p <= 9; ++p)
            ans = (ans + (bas + 1LL * p * diff[di]) % MOD1) % MOD2;
        return;
    }
    int mid = (di + i) / 2;
    q1[0] = q2[0] = 0;
    gen(i + 1, mid, q1, bas);
    gen(mid + 1, di, q2, 0);
    sort(q2 + 1, q2 + q2[0] + 1);
    long long sum = 0;
    for (int k = 1; k <= q2[0]; ++k)
        sum = (sum + q2[k]) % MOD2;
    for (int k = 1; k <= q1[0]; ++k) {
        int p = lower_bound(q2 + 1, q2 + q2[0] + 1, (int)(MOD1 - q1[k])) - q2;
        ans = (ans + sum + 1LL * q2[0] * q1[k]) % MOD2;
        ans = (ans + 1LL * (q2[0] - p + 1) * (MOD2 - MOD1)) % MOD2;
    }
}

int main() {
    scanf("%lld", &N);
    for (long long m = N; m; d[++d[0]] = m % 10, m /= 10);
    reverse(d + 1, d + d[0] + 1);
    for (int di = 1; di <= d[0]; ++di) {
        for (int i = 1; i <= di; ++i) {
            int l = (i == 1 ? 1 : 0);
            int r = (di == d[0] ? d[i] - 1 : 9);
            for (int j = l; j <= r; ++j)
                if (j != d[i]) upd(di, i, j);
        }
        ans = (ans + F(d, di)) % MOD2;
    }
    printf("%d\n", ans);
    return 0;
}
